    best={tgt:E}; pq=[(-E,tgt)]
    while pq:
        nt,u=heapq.heappop(pq); t0=-nt
        if t0<best.get(u,-1): continue
        lst=inn.get(u,[]); i=bisect.bisect_right(lst,(t0,float('inf')))
